frontend/src/style.css
```
:root {
  color-scheme: light dark;
  --bg: #f7f7f5;
  --fg: #1d1d1b;
  --muted: #6a6a66;
  --border: #d9d9d4;
  --accent: #2563eb;
  --accent-fg: #ffffff;
  --danger: #b42318;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #161616;
    --fg: #f1f1ee;
    --muted: #a3a39d;
    --border: #3a3a37;
    --accent: #6ea0ff;
    --accent-fg: #0b1220;
    --danger: #ff8a7a;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  overflow-x: hidden;
}

body {
  background: var(--bg);
  color: var(--fg);
  font-family: system-ui, sans-serif;
  line-height: 1.4;
}

.page {
  max-width: 32rem;
  margin: 0 auto;
  padding: 1rem;
}

h1 {
  margin: 0 0 1rem;
  font-size: 1.5rem;
}

.add-form {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.add-form label {
  flex-basis: 100%;
}

input[type="text"] {
  flex: 1 1 10rem;
  min-width: 0;
  min-height: 44px;
  padding: 0 0.75rem;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  background: transparent;
  color: inherit;
  font: inherit;
}

button {
  min-height: 44px;
  min-width: 44px;
  padding: 0 1rem;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.add-form button {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-fg);
}

input[type="checkbox"] {
  flex: none;
  min-width: 44px;
  min-height: 44px;
  margin: 0;
  accent-color: var(--accent);
}

.todo-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  min-height: 44px;
  border-bottom: 1px solid var(--border);
}

.todo-item label {
  display: flex;
  flex: 1;
  align-items: center;
  min-width: 0;
  overflow-wrap: anywhere;
}

.todo-item.done span {
  color: var(--muted);
  text-decoration: line-through;
}

.empty,
.loading {
  color: var(--muted);
}

.error {
  flex-basis: 100%;
  margin: 0;
  color: var(--danger);
}
```

